_NAICS_BY_CODE: Final = {item.code: item for item in _INDUSTRIES}
_NAICS_SECTOR_BY_ID: Final = {item.value: item for item in IndustrySector}
_NAICS_SECTOR_BY_CODE: Final = {item.code: item for item in IndustrySector}
_NAICS_CHILD_LISTS: dict[str, list[Industry]] = {}
for _naics_item in _INDUSTRIES:
    if _naics_item.parent_code is not None:
        _NAICS_CHILD_LISTS.setdefault(_naics_item.parent_code, []).append(_naics_item)
_NAICS_CHILDREN: Final = {
    code: tuple(items) for code, items in _NAICS_CHILD_LISTS.items()
}
del _NAICS_CHILD_LISTS, _naics_item
ALL_INDUSTRIES: Final = _INDUSTRIES
SECTORS: Final = tuple(IndustrySector)
SECTOR_ENTRIES: Final = tuple(
    item for item in _INDUSTRIES if item.level is IndustryLevel.SECTOR
)


def resolve_industry(code: str | None) -> Industry | None:
    return _NAICS_BY_CODE.get(code) if isinstance(code, str) else None


def children_of(code: str) -> tuple[Industry, ...]:
    return _NAICS_CHILDREN.get(code, ())


class SicLevel(str, Enum):
    DIVISION = ('division', 1)
    MAJOR_GROUP = ('major_group', 2)
    INDUSTRY_GROUP = ('industry_group', 3)
    INDUSTRY = ('industry', 4)
    QCEW_ROLLUP = ('qcew_rollup', 4)

    def __new__(cls, value: str, depth: int) -> SicLevel:
        member = str.__new__(cls, value)
        member._value_ = value
        member.depth = depth
        return member

    depth: int


class SicDivision(str, Enum):
    AGRICULTURE_FORESTRY_FISHING = ('agriculture_forestry_fishing', 'A', 'Agriculture, Forestry, and Fishing Division', 'agriculture', 'Agriculture, forestry, fishing, hunting, and related services')
    ALL_INDUSTRIES = ('all_industries', 'Z', 'All Industries', 'category', 'Aggregate covering every SIC division')
    CONSTRUCTION = ('construction', 'C', 'Construction Division', 'construction', 'Building construction and special trade contractors')
    FINANCE_INSURANCE_REAL_ESTATE = ('finance_insurance_real_estate', 'H', 'Finance, Insurance, and Real Estate Division', 'account_balance', 'Depository institutions, finance, insurance, and real estate')
    MANUFACTURING = ('manufacturing', 'D', 'Manufacturing Division', 'factory', 'Manufacturing of durable and nondurable goods')
    MINING = ('mining', 'B', 'Mining Division', 'terrain', 'Metal, coal, oil and gas, and nonmetallic mineral extraction')
    NONCLASSIFIABLE = ('nonclassifiable', 'K', 'Nonclassifiable Establishments', 'help_outline', 'Establishments that cannot be classified elsewhere')
    PUBLIC_ADMINISTRATION = ('public_administration', 'J', 'Public Administration Division', 'account_balance', 'Executive legislative judicial and public administration')
    RETAIL_TRADE = ('retail_trade', 'G', 'Retail Trade Division', 'storefront', 'Retailers selling merchandise and related services')
    SERVICES = ('services', 'I', 'Services Division', 'work', 'Business personal professional social and other services')
    TRANSPORTATION_COMMUNICATIONS_UTILITIES = ('transportation_communications_utilities', 'E', 'Transportation and Public Utilities Division', 'local_shipping', 'Transportation, communications, and public utilities')
    WHOLESALE_TRADE = ('wholesale_trade', 'F', 'Wholesale Trade Division', 'warehouse', 'Wholesalers and distributors of merchandise')

    def __new__(
        cls, value: str, code: str, label: str, material_symbol: str, description: str
    ) -> SicDivision:
        member = str.__new__(cls, value)
        member._value_ = value
        member.code = code
        member.label = label
        member.material_symbol = material_symbol
        member.description = description
        return member

    code: str
    label: str
    material_symbol: str
    description: str

    @classmethod
    def try_parse(cls, value: str) -> SicDivision | None:
        return _SIC_DIVISION_BY_ID.get(value)

    @classmethod
    def from_code(cls, code: str) -> SicDivision | None:
        return _SIC_DIVISION_BY_CODE.get(code)


@dataclass(frozen=True, slots=True)
class SicIndustry:
    code: str
    title: str
    level: SicLevel
    parent_code: str | None
    division_code: str

    @property
    def parent(self) -> SicIndustry | None:
        return resolve_sic(self.parent_code) if self.parent_code else None

    @property
    def division(self) -> SicDivision:
        return _SIC_DIVISION_BY_CODE[self.division_code]

    @property
    def division_entry(self) -> SicIndustry:
        return _SIC_BY_CODE[self.division_code]

    @property
    def children(self) -> tuple[SicIndustry, ...]:
        return _SIC_CHILDREN.get(self.code, ())

    @property
    def material_symbol(self) -> str:
        return self.division.material_symbol


